<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{JobWorkerProcess,MariaDbJobQueue,MariaDbWorkerHeartbeat};
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_worker_stale_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='stale_';$clock=sys_get_temp_dir().'/fm2-worker-clock-'.bin2hex(random_bytes(5));file_put_contents($clock,'2026-09-09T10:00:00.000000Z');putenv('JOBS_CLOCK_FILE='.$clock);
try{JobsSchemaMigration::apply($db,$p);$now=static fn():string=>trim(file_get_contents($clock));$queue=new MariaDbJobQueue($db,$p,$now,static fn():string=>str_repeat('a',64),['test.stale'=>[1]]);$job=$queue->enqueue(['jobType'=>'test.stale','payloadVersion'=>1,'payload'=>['value'=>1],'availableAtUtc'=>$now(),'idempotencyKey'=>'ffffffff-ffff-4fff-8fff-ffffffffffff','actor'=>['type'=>'system','id'=>'stale-test']]);$worker=new JobWorkerProcess($queue,new MariaDbWorkerHeartbeat($db,$p),['test.stale'=>[1=>static fn(array$j):array=>[PHP_BINARY,dirname(__DIR__).'/Support/jobs_stale_handler.php']]],$now,'stale-worker',1,10000,2);$result=$worker->run();assertSameValue(['lost_lease',0,70],[$result['status'],$result['completed'],$result['exitCode']],'expired lease settlement is reported lost, never completed');$state=$db->query("SELECT status,attempt,result_json FROM `{$p}fm2_jobs` WHERE job_id=".(int)$job['jobId'])->fetch_assoc();assertSameValue(['leased',1,null],[$state['status'],(int)$state['attempt'],$state['result_json']],'stale handler result changes no job terminal state');assertSameValue(0,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_job_events` WHERE job_id=".(int)$job['jobId']." AND event_type='completed'")->fetch_assoc()['n'],'lost lease appends no false completed event');echo"PASS: JOBS-WORKER-RUNTIME-001 stale settlement is not success\n";
}finally{putenv('JOBS_CLOCK_FILE');unlink($clock);$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
